(56, '<p>Good Evening Devs</p>\r\n<ul>\r\n<ul>\r\n<li><strong>Web Penter Work</strong> <span class=\"In Progress\">[In Progress]</span></li>\r\n</ul>\r\n</ul>\r\n<div style=\"color: #ffffff; background-color: #000000; font-family: Consolas, \'Courier New\', monospace; line-height: 19px; white-space: pre;\">\r\n<div>&nbsp;</div>\r\n<div><span style=\"color: #808080;\">&lt;</span><span style=\"color: #569cd6;\">html</span> <span style=\"color: #9cdcfe;\">lang</span>=<span style=\"color: #ce9178;\">\"en\"</span><span style=\"color: #808080;\">&gt;</span></div>\r\n<div><span style=\"color: #808080;\">&lt;html&gt;</span></div>\r\n<div><span style=\"color: #808080;\">&lt;</span><span style=\"color: #569cd6;\">head</span><span style=\"color: #808080;\">&gt;</span></div>\r\n<div>&nbsp;</div>\r\n<div>&nbsp; &nbsp; <span style=\"color: #808080;\">&lt;</span><span style=\"color: #569cd6;\">style</span><span style=\"color: #808080;\">&gt;</span></div>\r\n<div>&nbsp;<span style=\"color: #d7ba7d;\">.div-1</span>{</div>\r\n<div>&nbsp; &nbsp; <span style=\"color: #d4d4d4;\">border</span>: <span style=\"color: #b5cea8;\">2px</span> <span style=\"color: #ce9178;\">solid</span> <span style=\"color: #ce9178;\">green</span>;</div>\r\n<div>&nbsp; &nbsp; <span style=\"color: #d4d4d4;\">text-align</span>: <span style=\"color: #ce9178;\">center</span>;</div>\r\n<div>&nbsp; &nbsp; <span style=\"color: #d4d4d4;\">margin</span>: <span style=\"color: #ce9178;\">auto</span>;</div>\r\n<div>&nbsp; &nbsp; <span style=\"color: #d4d4d4;\">width</span>: <span style=\"color: #b5cea8;\">50%</span>;</div>\r\n<div>&nbsp; &nbsp; <span style=\"color: #d4d4d4;\">padding</span>:<span style=\"color: #b5cea8;\">8px</span>; &nbsp;</div>\r\n<div>&nbsp; &nbsp; <span style=\"color: #d4d4d4;\">clear</span>: <span style=\"color: #ce9178;\">both</span>;</div>\r\n<div>&nbsp; &nbsp; <span style=\"color: #d4d4d4;\">display</span>: <span style=\"color: #ce9178;\">table</span>;</div>\r\n<div>&nbsp;</div>\r\n<div>}</div>\r\n<div>&nbsp;</div>\r\n<div>&nbsp;</div>\r\n<div>&nbsp;<span style=\"color: #d7ba7d;\">img</span>{</div>\r\n<div>&nbsp; &nbsp; <span style=\"color: #d4d4d4;\">display</span>: <span style=\"color: #ce9178;\">block</span>;</div>\r\n<div>&nbsp; &nbsp; <span style=\"color: #d4d4d4;\">margin-left</span>: <span style=\"color: #ce9178;\">auto</span>;</div>\r\n<div>&nbsp; &nbsp; <span style=\"color: #d4d4d4;\">margin-right</span>: <span style=\"color: #ce9178;\">auto</span>;</div>\r\n<div>&nbsp; &nbsp; <span style=\"color: #d4d4d4;\">width</span>: <span style=\"color: #b5cea8;\">50%</span>;</div>\r\n<div>&nbsp; &nbsp; <span style=\"color: #d4d4d4;\">float</span>: <span style=\"color: #ce9178;\">right</span>;</div>\r\n<div>&nbsp; &nbsp;</div>\r\n<div>&nbsp;}</div>\r\n<div>&nbsp;<span style=\"color: #d7ba7d;\">.div-2</span>{</div>\r\n<div>&nbsp; &nbsp; <span style=\"color: #d4d4d4;\">position</span>: <span style=\"color: #ce9178;\">absolute</span>;</div>\r\n<div>&nbsp; &nbsp; <span style=\"color: #d4d4d4;\">right</span>: <span style=\"color: #b5cea8;\">0%</span>;</div>\r\n<div>&nbsp; &nbsp; <span style=\"color: #d4d4d4;\">width</span>: <span style=\"color: #b5cea8;\">250px</span>;</div>\r\n<div>&nbsp; &nbsp; <span style=\"color: #d4d4d4;\">border</span>: <span style=\"color: #b5cea8;\">2px</span> <span style=\"color: #ce9178;\">solid</span> <span style=\"color: #ce9178;\">gray</span>;</div>\r\n<div>&nbsp; &nbsp; <span style=\"color: #d4d4d4;\">padding</span>: <span style=\"color: #b5cea8;\">20px</span>;</div>\r\n<div>&nbsp;}</div>\r\n<div>&nbsp;<span style=\"color: #d7ba7d;\">.div-3</span>{</div>\r\n<div>&nbsp; &nbsp; <span style=\"color: #d4d4d4;\">float</span>: <span style=\"color: #ce9178;\">left</span>;</div>\r\n<div>&nbsp; &nbsp; <span style=\"color: #d4d4d4;\">border</span>: <span style=\"color: #b5cea8;\">2px</span> <span style=\"color: #ce9178;\">solid</span> <span style=\"color: #ce9178;\">blue</span>;</div>\r\n<div>&nbsp; &nbsp; <span style=\"color: #d4d4d4;\">paddin