(273, '<p>1-function:</p>\r\n<p>&nbsp; &nbsp; &nbsp;1-simple function =&gt;</p>\r\n<p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &lt;?php</p>\r\n<p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; function add_number($firstnumber,$secondnumber){</p>\r\n<p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;$result =$firstnumber+$secondnumber;</p>\r\n<p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;return $result;</p>\r\n<p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; }</p>\r\n<p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;print add_number(10,30);</p>\r\n<p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; ?&gt;</p>\r\n<p>&nbsp; &nbsp; &nbsp;2-biltinfunction</p>\r\n<p>&nbsp; &nbsp; &nbsp;3-Global function</p>\r\n<p>&nbsp; &nbsp; &nbsp;4-Static function</p>\r\n<p>2-ARRAY =&gt;</p>\r\n<p>&lt;?php</p>\r\n<p>$employees = array(\"employee1\" =&gt; array (</p>\r\n<p>&nbsp; &nbsp; \"name\"=&gt;\"Abdul khaliq\",</p>\r\n<p>&nbsp; &nbsp; \"Designation\"=&gt;\"Webdevloper\",</p>\r\n<p>&nbsp; &nbsp; \"Age\" =&gt; 26,</p>\r\n<p>&nbsp; &nbsp; \"Skills\" =&gt; \"Html,Css,Java,Php\"</p>\r\n<p>),</p>\r\n<p>\"employee2\" =&gt; array (</p>\r\n<p>&nbsp; &nbsp; \"name\"=&gt;\"Arif\",</p>\r\n<p>&nbsp; &nbsp; \"Designation\"=&gt;\"Appdevloper\",</p>\r\n<p>&nbsp; &nbsp; \"Age\" =&gt; 29,</p>\r\n<p>&nbsp; &nbsp; \"Skills\" =&gt; \"Html,Css,Java,Php,React\"</p>\r\n<p>),</p>\r\n<p>\"employee3\" =&gt; array (</p>\r\n<p>&nbsp; &nbsp; \"name\"=&gt;\"Waqas\",</p>\r\n<p>&nbsp; &nbsp; \"Designation\"=&gt;\"SEO\",</p>\r\n<p>&nbsp; &nbsp; \"Age\" =&gt; 28,</p>\r\n<p>&nbsp; &nbsp; \"Skills\" =&gt; \"website SEO,wordpress\"</p>\r\n<p>),</p>\r\n<p>\"employee4\" =&gt; array(</p>\r\n<p>&nbsp; &nbsp; \"name\"=&gt;\"Sadiq\",</p>\r\n<p>&nbsp; &nbsp; \"Designation\" =&gt;\"Webdevloper\",</p>\r\n<p>&nbsp; &nbsp; \"Age\" =&gt; 32,</p>\r\n<p>&nbsp; &nbsp; \"skills\"=&gt; \"php,laraevl,Reactjs\"</p>\r\n<p>),</p>\r\n<p>);</p>\r\n<p>print $employees[\"employee2\"][\"Designation\"];&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;( output=&gt;Appdevloper)</p>\r\n<p>echo\"&lt;/br&gt;\";</p>\r\n<p>print $em</p>', '<p>Array with loop</p>', 31, 18, '2023-07-12 18:03:39', '2023-07-12 18:03:39'),
