INSERT INTO `leaves` (`id`, `user_id`, `start_date`, `reason`, `created_at`, `updated_at`, `deleted_at`, `end_date`) VALUES
(2, 65, '2023-12-15', 'WebPenter Software House\r\nZahir Peer\r\n\r\nAssalam-o-Alaikum!,\r\n\r\nMujhe umeed hai ke aap khairiyat se honge. Main Amir Hussain  hoon aur mujhe yeh likh kar khushi hui ke main WebPenter Software House mein kaam Seekh Raha hoon.\r\n\r\nMain is liye yeh application likh raha hoon ke mere ghar par kuch zaroori kaam urgent taur par anjaam dene ke liye mujhe chutti ki darkhwast karni hai. Mujhe yakeen hai ke main apni zimmedariyon ka dhyaan rakh kar kaam karta hoon, lekin is dafa mujhe ghar par mohlat chahiye hai taake main apne zaroori kaamon ko pura kar saku.\r\n\r\nMai koshish karunga ke meri chutti ka asar kaam mein kam ho aur main apne kaam ko jald se jald pura karke wapas aaoon ga.\r\n\r\nMain aapke samajh aur madad ke liye mashkoor honga.\r\n\r\nShukriya,\r\nAmir Hussain\r\nStudent\r\n0336-7814467', '2023-12-14 14:55:37', '2023-12-14 14:55:37', NULL, NULL),
